describe('Async Operation Cancellation', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
  });

  it('should cancel an async operation when abort button is clicked', () => {
    cy.get('[data-testid="start-async-btn"]').click();
    cy.get('[data-testid="abort-btn"]').should('be.visible');
    cy.get('[data-testid="abort-btn"]').click();
    cy.get('[data-testid="operation-status"]').should('contain', 'Cancelled');
    cy.get('[data-testid="loading-spinner"]').should('not.exist');
  });

  it('should complete async operation successfully when abort button is not clicked', () => {
    cy.get('[data-testid="start-async-btn"]').click();
    cy.get('[data-testid="loading-spinner"]').should('be.visible');
    cy.get('[data-testid="operation-status"]', { timeout: 10000 }).should('contain', 'Completed');
    cy.get('[data-testid="result-data"]').should('be.visible');
  });

  it('should disable abort button after operation completes', () => {
    cy.get('[data-testid="start-async-btn"]').click();
    cy.get('[data-testid="operation-status"]', { timeout: 10000 }).should('contain', 'Completed');
    cy.get('[data-testid="abort-btn"]').should('be.disabled');
  });

  it('should handle rapid abort clicks gracefully', () => {
    cy.get('[data-testid="start-async-btn"]').click();
    cy.get('[data-testid="abort-btn"]').click();
    cy.get('[data-testid="abort-btn"]').click();
    cy.get('[data-testid="abort-btn"]').click();
    cy.get('[data-testid="operation-status"]').should('contain', 'Cancelled');
    cy.get('[data-testid="error-message"]').should('not.exist');
  });

  it('should show abort button only during async operation', () => {
    cy.get('[data-testid="abort-btn"]').should('not.exist');
    cy.get('[data-testid="start-async-btn"]').click();
    cy.get('[data-testid="abort-btn"]').should('be.visible');
    cy.get('[data-testid="operation-status"]', { timeout: 10000 }).should('contain', 'Completed');
    cy.get('[data-testid="abort-btn"]').should('not.exist');
  });
});
